package com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.spec.skill;import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.identity.StableId;public final class RedirectDamageEffectSpec implements EffectSpec{private final StableId effectId;private final int percent;private final SubjectSelector recipient;private final DurationSpec duration;public RedirectDamageEffectSpec(StableId id,int percent,SubjectSelector recipient,DurationSpec duration){if(id==null||recipient==null||duration==null||percent<1||percent>75)throw new IllegalArgumentException("invalid redirect fields");effectId=id;this.percent=percent;this.recipient=recipient;this.duration=duration;}@Override public StableId effectId(){return effectId;}@Override public EffectFamily family(){return EffectFamily.RECOVERY_DEFENSE;}@Override public EffectVariantKey variantKey(){return EffectVariantKey.REDIRECT_DAMAGE;}public int percent(){return percent;}public SubjectSelector recipient(){return recipient;}public DurationSpec duration(){return duration;}}
